class Compressor:
    """Output-balanced error-feedback sparsifier.

    Key idea: global TopK often starves entire output channels / filters under
    extreme sparsity. We instead reshape weight tensors as [out_dim, -1] and
    keep a small TopK *per row*, so every filter/classifier output receives an
    update each step. Small tensors (bias/BN/statistics) are sent densely since
    they are communication-negligible but optimization-critical.
    """

    def __init__(self, compress_ratio=0.01):
        self.compress_ratio = compress_ratio
        self.residuals = {}
        self.dense_threshold = 2048
        self.residual_clip = 2.5

    def compress(self, tensor, name):
        buf = tensor
        if name in self.residuals:
            buf = buf + self.residuals[name]

        shape = tensor.shape
        numel = buf.numel()
        if numel <= self.dense_threshold or tensor.ndim <= 1:
            self.residuals[name] = torch.zeros_like(tensor)
            return [buf.clone()], ("dense", shape)

        mat = buf.reshape(shape[0], -1)
        rows, cols = mat.shape
        k_row = max(1, int(cols * self.compress_ratio))
        if k_row >= cols:
            self.residuals[name] = torch.zeros_like(tensor)
            return [buf.clone()], ("dense", shape)

        indices = torch.topk(mat.abs(), k_row, dim=1, sorted=False).indices
        values = mat.gather(1, indices)

        recon = torch.zeros_like(mat)
        recon.scatter_(1, indices, values)
        residual = mat - recon

        base_norm = mat.norm()
        residual_norm = residual.norm()
        if base_norm > 0 and residual_norm > self.residual_clip * base_norm:
            residual = residual * (self.residual_clip * base_norm / (residual_norm + 1e-12))
        self.residuals[name] = residual.view(shape)

        offsets = torch.arange(rows, device=tensor.device).unsqueeze(1) * cols
        flat_indices = (indices + offsets).reshape(-1)
        return [values.reshape(-1), flat_indices], ("sparse", numel, shape)

    def decompress(self, compressed_tensors, ctx):
        mode = ctx[0]
        if mode == "dense":
            return compressed_tensors[0].view(ctx[1])

        _, numel, shape = ctx
        values, indices = compressed_tensors
        out = torch.zeros(numel, dtype=values.dtype, device=values.device)
        out.scatter_(0, indices, values)
        return out.view(shape)
